package Operators;

public class Bitwise {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int x = 5, y = 3; // Example values
		System.out.println("AND: " + (x & y));
		System.out.println("OR: " + (x | y));
		System.out.println("XOR: " + (x ^ y));


	}

}
